package com.arjunren.leave.repository;
import com.arjunren.leave.domain.*; import com.arjunren.leave.entity.LeaveRequest; import jakarta.persistence.LockModeType; import java.time.LocalDate; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface LeaveRequestRepository extends JpaRepository<LeaveRequest,Long>{Page<LeaveRequest>findByEmployeeUserId(Long id,Pageable p);Page<LeaveRequest>findByEmployeeManagerId(Long id,Pageable p);Page<LeaveRequest>findByStatus(LeaveStatus s,Pageable p);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select l from LeaveRequest l join fetch l.employee e join fetch e.user left join fetch e.manager where l.id=:id")Optional<LeaveRequest>findByIdForUpdate(@Param("id")Long id);@Query("select count(l)>0 from LeaveRequest l where l.employee.id=:employeeId and l.status in :statuses and l.startDate<=:end and l.endDate>=:start")boolean hasOverlap(@Param("employeeId")Long employeeId,@Param("statuses")Collection<LeaveStatus>statuses,@Param("start")LocalDate start,@Param("end")LocalDate end);long countByStatus(LeaveStatus s);}

